create table if not exists files (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  file_ref text not null,\n  property_address text not null,\n  status text not null default 'open' check (status in ('open', 'closed')),\n  notes text,\n  created_at timestamptz not null default now()\n);\n\nalter table files enable row level security;\n\ndrop policy if exists \"files_v1_read\" on files;\ncreate policy \"files_v1_read\" on files for select using (true);\ndrop policy if exists \"files_v1_write\" on files;\ncreate policy \"files_v1_write\" on files for all using (true) with check (true);\n\ncreate table if not exists purchasers (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  file_id uuid not null,\n  name text not null,\n  signing_status text not null default 'pending' check (signing_status in ('pending', 'signed')),\n  signing_date date,\n  follow_up_needed boolean not null default false,\n  follow_up_notes text,\n  created_at timestamptz not null default now()\n);\n\nalter table purchasers enable row level security;\n\ndrop policy if exists \"purchasers_v1_read\" on purchasers;\ncreate policy \"purchasers_v1_read\" on purchasers for select using (true);\ndrop policy if exists \"purchasers_v1_write\" on purchasers;\ncreate policy \"purchasers_v1_write\" on purchasers for all using (true) with check (true);\n\ninsert into files (file_ref, property_address, status, notes) values\n  ('PT-2024-0137', '12 Oak Avenue, Leeds', 'open', 'Standard residential transfer. Two joint purchasers.'),\n  ('PT-2024-0152', '34 Kings Road, Manchester', 'open', 'Trustee purchase — three parties on title.'),\n  ('PT-2024-0168', '7 Station Lane, York', 'closed', 'Completed transfer. All forms signed.')\non conflict do nothing;\n\ninsert into purchasers (file_id, name, signing_status, signing_date, follow_up_needed, follow_up_notes) values\n  ( (select id from files where file_ref = 'PT-2024-0137'), 'John Smith', 'signed', '2024-06-15', false, null ),\n  ( (select id from files where file_ref = 'PT-2024-0137'), 'Mary Smith', 'pending', null, true, 'Solicitor chasing — no response since 10 June.' ),\n  ( (select id from files where file_ref = 'PT-2024-0152'), 'David Brown', 'signed', '2024-06-20', false, null ),\n  ( (select id from files where file_ref = 'PT-2024-0152'), 'Sarah Brown', 'pending', null, false, null ),\n  ( (select id from files where file_ref = 'PT-2024-0152'), 'James Wilson (trustee)', 'pending', null, true, 'Trustee not yet contacted.' ),\n  ( (select id from files where file_ref = 'PT-2024-0168'), 'Robert Taylor', 'signed', '2024-05-10', false, null ),\n  ( (select id from files where file_ref = 'PT-2024-0168'), 'Emma Taylor', 'signed', '2024-05-10', false, null )\non conflict do nothing;